    ["reportsAccessMount", "reportsFinanceMount"].forEach((id) => {
      if ($(id)) $(id).innerHTML = `<section class="panel-card"><p>Nao foi possivel montar este relatorio. Use Atualizar para tentar novamente.</p></section>`;
    });
