async function updateBenefitQuestion(question, status, response = question.response || "") {
  const now = Date.now();
  const partnerId = question.partnerId || question.benefitId;
  const updates = {
    [`beneficiosDuvidas/${partnerId}/${question.id}/status`]: status,
    [`beneficiosDuvidas/${partnerId}/${question.id}/response`]: response,
    [`beneficiosDuvidas/${partnerId}/${question.id}/updatedAt`]: now,
    [`beneficiosDuvidas/${partnerId}/${question.id}/updatedBy`]: state.user?.uid || "",
    [`beneficiosDuvidasPorCliente/${question.clientId}/${question.id}/status`]: status,
    [`beneficiosDuvidasPorCliente/${question.clientId}/${question.id}/response`]: response,
    [`beneficiosDuvidasPorCliente/${question.clientId}/${question.id}/updatedAt`]: now,
    [`beneficiosDuvidasPorCliente/${question.clientId}/${question.id}/updatedBy`]: state.user?.uid || ""
  };
  if (response || status === "respondida") {
    const notificationId = push(ref(db, `beneficiosNotificacoesCliente/${question.clientId}`)).key;
    updates[`beneficiosNotificacoesCliente/${question.clientId}/${notificationId}`] = {
      type: "resposta_duvida", partnerId, clientId: question.clientId, actorUid: state.user?.uid || "", questionId: question.id,
      message: `${question.partnerName || "O parceiro"} respondeu sua dúvida.`, createdAt: now
    };
  }
  await update(ref(db), updates);
}

function bindPartnerBenefitsArea() {
  const mount = $("partnerBenefitsMount");
  if (!mount) return;
  const partnerRequests = isMaster() ? state.beneficiosUtilizacoes : state.beneficiosParceiroSolicitacoes;
  const partnerQuestions = isMaster() ? state.beneficiosDuvidas : state.beneficiosParceiroDuvidas;
  mount.querySelector("#masterPartnerAreaSelect")?.addEventListener("change", (event) => {
    state.selectedBenefitDetailId = event.target.value;
    renderPartnerBenefitsArea();
  });
  mount.querySelectorAll("[data-partner-request-status]").forEach((select) => select.addEventListener("change", async () => {
    const request = partnerRequests.find((item) => item.id === select.dataset.partnerRequestStatus);
    if (!request) return;
    const needsNote = ["informacoes_solicitadas", "recusada"].includes(select.value);
    const note = needsNote ? (window.prompt("Informe a orientação ou motivo que será enviado ao cliente:") || "") : "";
    if (needsNote && !note) {
      select.value = request.status;
      return;
    }
    select.disabled = true;
    try { await updateBenefitRequestStatus(request, select.value, note); showToast("Solicitação atualizada e cliente notificado."); } finally { select.disabled = false; }
  }));
  mount.querySelectorAll("[data-partner-question-status]").forEach((select) => select.addEventListener("change", async () => {
    const question = partnerQuestions.find((item) => item.id === select.dataset.partnerQuestionStatus);
    if (!question) return;
    await updateBenefitQuestion(question, select.value);
    showToast("Situação da dúvida atualizada.");
  }));
  mount.querySelectorAll("[data-partner-question-response]").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const question = partnerQuestions.find((item) => item.id === form.dataset.partnerQuestionResponse);
    if (!question) return;
    const response = form.querySelector("textarea")?.value.trim() || "";
    if (!response) return showToast("Escreva uma resposta.");
    const button = event.submitter;
    setBusy(button, true, "Salvando...");
    try { await updateBenefitQuestion(question, "respondida", response); showToast("Resposta salva e cliente notificado."); } finally { setBusy(button, false); }
  }));
  mount.querySelectorAll("[data-benefit-notification-read]").forEach((button) => button.addEventListener("click", () => markBenefitNotificationRead(button.dataset.benefitNotificationRead, "partner")));
}

function deletionReportFilteredItems() {
  const filters = state.deletionReportFilters || {};
  const search = normalizeName(filters.search || "");
  const type = String(filters.type || "todos");
  const actor = String(filters.actor || "todos");
  const days = Number(filters.period || 0);
  const cutoff = days > 0 ? Date.now() - (days * 86400000) : 0;
  return (state.exclusoes || []).filter((item) => {
    if (type !== "todos" && item.tipo !== type) return false;
    if (actor !== "todos" && item.email !== actor) return false;
    if (cutoff && Number(item.createdAt || 0) < cutoff) return false;
    if (!search) return true;
    const haystack = normalizeName([
      item.referencia,
      item.tipo,
      item.clienteNome,
      item.clienteId,
      item.email,
      item.itemId,
      item.detalhes
    ].filter(Boolean).join(" "));
    return haystack.includes(search);
  });
}
function deletionWhatsappIdentity(value = "") {
  return normalizeName(String(value || "").replace(/^(id|ref):/i, "").trim());
}

function deletionWhatsappClientKeys(item = {}) {
  const linkedClient = state.clientes.find((client) => (
    String(client.id || "") === String(item.clienteId || "")
    || normalizeName(client.nome || client.name || "") === normalizeName(item.clienteNome || "")
  ));
  return [...new Set([
    item.clienteId,
    item.clienteNome,
    linkedClient?.id,
    linkedClient?.nome,
    linkedClient?.name,
    linkedClient?.nomeNormalizado,
    linkedClient ? clientCanonicalId(linkedClient) : "",
    ...Object.keys(linkedClient?.aliases || {})
  ].flatMap(aliasKeyVariants).map((value) => normalizeName(value)).filter(Boolean))];
}

function deletionWhatsappTypeMatches(item = {}, log = {}) {
  const recordType = normalizeName(item.tipo || "");
  const logType = normalizeName([log.tipo, log.grupo, log.area, log.acao].filter(Boolean).join(" "));
  const rules = [
    [/imovel/, /imovel/],
    [/automovel|veiculo/, /automovel|veiculo/],
    [/produto/, /produto/],
    [/promocao/, /promocao/],
    [/vaga/, /vaga/],
    [/noticia/, /noticia/],
    [/evento/, /evento/]
  ];
  const rule = rules.find(([recordPattern]) => recordPattern.test(recordType));
  return !rule || rule[1].test(logType);
}

function deletionWhatsappCount(item = {}) {
  if (!state.deletionWhatsappMetricsLoaded) return null;
  const recordIds = new Set([
    item.itemId,
    String(item.caminho || "").split("/").filter(Boolean).pop()
  ].map(deletionWhatsappIdentity).filter(Boolean));
  const recordReference = normalizeName(item.referencia || "");
  const clientKeys = deletionWhatsappClientKeys(item);

  return (state.deletionWhatsappLogs || []).reduce((total, entry) => {
    const log = entry.log || {};
    if (clientKeys.length && !metricKeyBelongsToClient(entry.clientKey, clientKeys)) return total;
    if (!deletionWhatsappTypeMatches(item, log)) return total;

    const logIds = [
      log.itemId,
      log.imovelId,
      log.veiculoId,
      log.automovelId,
      log.produtoId,
      log.promoId,
      log.promocaoId,
      log.vagaId,
      log.noticiaId,
      log.eventoId,
      log.codRef,
      log.codigo
    ].map(deletionWhatsappIdentity).filter(Boolean);
    const idMatches = logIds.some((id) => recordIds.has(id));
    if (idMatches) return total + 1;

    if (!recordReference || logIds.length) return total;
    const logReferences = [
      log.tituloConteudo,
      log.imovelTitulo,
      log.promoTitulo,
      log.promocaoTitulo,
      log.titulo,
      log.nome
    ].map((value) => normalizeName(value || "")).filter(Boolean);
    const referenceMatches = logReferences.some((value) => (
      value === recordReference
      || (value.length > 5 && recordReference.length > 5 && (value.includes(recordReference) || recordReference.includes(value)))
    ));
    return total + (referenceMatches ? 1 : 0);
  }, 0);
}

async function loadDeletionWhatsappMetrics({ force = false } = {}) {
  if (!isMaster()) return [];
  if (state.deletionWhatsappMetricsLoaded && !force) return state.deletionWhatsappLogs;
  if (state.deletionWhatsappMetricsPromise && !force) return state.deletionWhatsappMetricsPromise;

  state.deletionWhatsappMetricsLoaded = false;
  state.deletionWhatsappMetricsPromise = (async () => {
    const snapshot = await get(ref(db, "metricasClientes"));
    const logs = [];
    const root = snapshot.exists() ? snapshot.val() : {};
    Object.entries(root || {}).forEach(([clientKey, days]) => {
      Object.values(days || {}).forEach((day) => {
        Object.values(day?.detalhes || {}).forEach((log) => {
          const action = normalizeName([log?.tipo, log?.acao, log?.area].filter(Boolean).join(" "));
          if (/whatsapp|whats|telefone|contato|zap/.test(action)) logs.push({ clientKey, log: log || {} });
        });
      });
    });
    state.deletionWhatsappLogs = logs;
    state.deletionWhatsappMetricsLoaded = true;
    return logs;
  })()
    .catch((error) => {
      console.warn("Nao foi possivel carregar os cliques de WhatsApp das exclusoes.", error);
      state.deletionWhatsappLogs = [];
      state.deletionWhatsappMetricsLoaded = true;
      return [];
    })
    .finally(() => {
      state.deletionWhatsappMetricsPromise = null;
    });

  return state.deletionWhatsappMetricsPromise;
}


function renderDeletionReportRows() {
  const rows = deletionReportFilteredItems();
  const tbody = $("deletionReportRows");
  if (!tbody) return;
  const todayKey = new Date().toLocaleDateString("pt-BR");
  const todayTotal = rows.filter((item) => new Date(Number(item.createdAt || 0)).toLocaleDateString("pt-BR") === todayKey).length;
  const clientAdminTotal = rows.filter((item) => item.role === "cliente").length;
  const uniqueActors = new Set(rows.map((item) => item.email).filter(Boolean)).size;
  if ($("deletionReportTotal")) $("deletionReportTotal").textContent = String(rows.length);
  if ($("deletionReportToday")) $("deletionReportToday").textContent = String(todayTotal);
  if ($("deletionReportClients")) $("deletionReportClients").textContent = String(clientAdminTotal);
  if ($("deletionReportActors")) $("deletionReportActors").textContent = String(uniqueActors);
  if ($("deletionReportResultCount")) {
    $("deletionReportResultCount").textContent = `${rows.length} exclusao${rows.length === 1 ? "" : "oes"} encontrada${rows.length === 1 ? "" : "s"}`;
  }
  tbody.innerHTML = rows.length ? rows.map((item) => {
    const createdAt = Number(item.createdAt || 0);
    const roleLabel = item.role === "cliente" ? "Admin cliente" : (item.role === "master" ? "Admin master" : (item.role || "Administrador"));
    const clientLabel = item.clienteNome || item.clienteId || "Item geral";
    const whatsappCount = deletionWhatsappCount(item);
    const whatsappLabel = whatsappCount === null ? "..." : String(whatsappCount);
    return `
      <tr>
        <td><strong>${escapeHtml(createdAt ? new Date(createdAt).toLocaleDateString("pt-BR") : "-")}</strong><small>${escapeHtml(createdAt ? new Date(createdAt).toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" }) : "")}</small></td>
        <td><span class="deletion-type-badge">${escapeHtml(item.tipo || "Item")}</span></td>
        <td><strong>${escapeHtml(item.referencia || "Item sem referencia")}</strong><small>ID: ${escapeHtml(item.itemId || "-")}</small></td>
        <td><strong>${escapeHtml(clientLabel)}</strong><small>${escapeHtml(item.clienteId && item.clienteNome ? item.clienteId : "")}</small></td>
        <td><strong>${escapeHtml(item.email || "-")}</strong><small>${escapeHtml(roleLabel)}</small></td>
        <td class="deletion-whatsapp-cell"><span class="deletion-whatsapp-count ${whatsappCount > 0 ? "has-clicks" : ""}"><i class="fa-brands fa-whatsapp"></i>${whatsappLabel}</span></td>
        <td>
          <details class="deletion-details">
            <summary>Ver dados</summary>
            <p>${escapeHtml(item.detalhes || "Nenhum detalhe adicional disponivel.")}</p>
            <small>Tela: ${escapeHtml(item.origemTela || "-")}</small>
          </details>
        </td>
      </tr>
    `;
  }).join("") : `<tr><td colspan="7"><div class="deletion-empty"><i class="fa-solid fa-shield-halved"></i><strong>Nenhuma exclusao encontrada</strong><span>Ajuste os filtros ou aguarde novos registros.</span></div></td></tr>`;
}

function renderDeletionReport() {
  const mount = $("deletionReportMount");
  if (!mount || !isMaster()) return;
  const types = [...new Set((state.exclusoes || []).map((item) => item.tipo).filter(Boolean))].sort((a, b) => a.localeCompare(b, "pt-BR"));
  const actors = [...new Set((state.exclusoes || []).map((item) => item.email).filter(Boolean))].sort((a, b) => a.localeCompare(b, "pt-BR"));
  const filters = state.deletionReportFilters || {};
  mount.innerHTML = `
    <section class="panel-card deletion-report-hero">
      <div>
        <span class="feature-kicker"><i class="fa-solid fa-shield-halved"></i> Auditoria de exclusoes</span>
        <h2>Itens removidos do sistema</h2>
        <p>Monitore o que foi excluido, por qual usuario e a qual cliente o item pertencia. Imagens nao sao armazenadas neste historico.</p>
      </div>
      <div class="deletion-report-icon"><i class="fa-solid fa-trash-can-arrow-up"></i></div>
    </section>
    <section class="deletion-report-stats">
      <article><span>Resultado atual</span><strong id="deletionReportTotal">0</strong></article>
      <article><span>Excluidos hoje</span><strong id="deletionReportToday">0</strong></article>
      <article><span>Por admins clientes</span><strong id="deletionReportClients">0</strong></article>
      <article><span>Usuarios envolvidos</span><strong id="deletionReportActors">0</strong></article>
    </section>
    <section class="panel-card deletion-report-filters">
      <label>Buscar
        <input id="deletionReportSearch" type="search" value="${escapeAttr(filters.search || "")}" placeholder="Nome, referencia, cliente ou usuario">
      </label>
      <label>Tipo de item
        <select id="deletionReportType">
          <option value="todos">Todos os itens</option>
          ${types.map((type) => `<option value="${escapeAttr(type)}" ${filters.type === type ? "selected" : ""}>${escapeHtml(type)}</option>`).join("")}
        </select>
      </label>
      <label>Quem excluiu
        <select id="deletionReportActor">
          <option value="todos">Todos os usuarios</option>
          ${actors.map((email) => `<option value="${escapeAttr(email)}" ${filters.actor === email ? "selected" : ""}>${escapeHtml(email)}</option>`).join("")}
        </select>
      </label>
      <label>Periodo
        <select id="deletionReportPeriod">
          <option value="7" ${filters.period === "7" ? "selected" : ""}>Ultimos 7 dias</option>
          <option value="30" ${filters.period === "30" ? "selected" : ""}>Ultimos 30 dias</option>
          <option value="90" ${filters.period === "90" ? "selected" : ""}>Ultimos 90 dias</option>
          <option value="0" ${filters.period === "0" ? "selected" : ""}>Todo o historico</option>
        </select>
      </label>
    </section>
    <section class="panel-card deletion-report-table-card">
      <div class="section-head">
        <div><h2>Historico detalhado</h2><p id="deletionReportResultCount">0 exclusoes encontradas</p></div>
        <button id="refreshDeletionReportButton" type="button"><i class="fa-solid fa-rotate"></i> Atualizar</button>
      </div>
      <div class="report-table-wrap">
        <table class="report-table deletion-report-table">
          <thead><tr><th>Data</th><th>Tipo</th><th>Item / referencia</th><th>Cliente</th><th>Excluido por</th><th>WhatsApp</th><th>Detalhes</th></tr></thead>
          <tbody id="deletionReportRows"></tbody>
        </table>
      </div>
    </section>
  `;
  $("deletionReportSearch")?.addEventListener("input", (event) => {
    state.deletionReportFilters.search = event.target.value;
    renderDeletionReportRows();
  });
  $("deletionReportType")?.addEventListener("change", (event) => {
    state.deletionReportFilters.type = event.target.value;
    renderDeletionReportRows();
  });
  $("deletionReportActor")?.addEventListener("change", (event) => {
    state.deletionReportFilters.actor = event.target.value;
    renderDeletionReportRows();
  });
  $("deletionReportPeriod")?.addEventListener("change", (event) => {
    state.deletionReportFilters.period = event.target.value;
    renderDeletionReportRows();
  });
  $("refreshDeletionReportButton")?.addEventListener("click", async (event) => {
    const button = event.currentTarget;
    setBusy(button, true, "Atualizando...");
    try {
      const snapshot = await get(ref(db, "auditoriaExclusoes"));
      state.exclusoes = [];
      if (snapshot.exists()) {
        snapshot.forEach((child) => {
          state.exclusoes.push({ id: child.key, ...child.val() });
          return false;
        });
      }
      state.exclusoes.sort((a, b) => Number(b.createdAt || 0) - Number(a.createdAt || 0));
      await loadDeletionWhatsappMetrics({ force: true });
      renderDeletionReport();
      showToast("Relatorio de exclusoes atualizado.");
    } catch (error) {
      showToast("Nao foi possivel atualizar o relatorio.");
    } finally {
      setBusy(button, false);
    }
  });
  renderDeletionReportRows();
  if (!$("relatorioExclusoesView")?.classList.contains("hidden") && !state.deletionWhatsappMetricsLoaded) {
    loadDeletionWhatsappMetrics().then(() => {
      if (!$("relatorioExclusoesView")?.classList.contains("hidden")) renderDeletionReportRows();
    });
  }
}

function syncAdminMenuActiveState(target) {
  document.querySelectorAll(".nav-admin button[data-view]").forEach((button) => {
    const isActive = button.dataset.view === target;
    button.classList.toggle("active", isActive);
    if (isActive) button.setAttribute("aria-current", "page");
    else button.removeAttribute("aria-current");
  });
}

function switchView(name) {
  const target = views[name] ? name : "dashboard";
  if (!canAccessView(target)) {
    switchView(initialViewForProfile());
    return;
  }
  if (target !== "relatorioAcessos") {
    cancelAccessReportViewLoading();
    stopAccessReportRealtime();
    stopMasterClientMetricsRealtime();
  }
  if (target !== "integracaoPagamento") stopPaymentIntegrationRealtime();
  document.querySelectorAll(".nav-admin button.admin-button-loading").forEach((button) => {
    button.classList.remove("admin-button-loading");
  });
  Object.entries(views).forEach(([key, el]) => el.classList.toggle("hidden", key !== target));
  syncAdminMenuActiveState(target);
  const [title, subtitle] = viewCopy[target];
  authenticatedClientPresenceView = title;
  touchAuthenticatedClientPresence(true, true);
  $("viewTitle").textContent = title;
  $("viewSubtitle").textContent = subtitle;
  collapseEntryFormsForView(target);

  if (target === "minhaEmpresa") {
    state.pendingClientModuleTarget = "";
    renderClientOnlyEditor();
  }
  if (target === "artesPostagem") renderPostArtView();
  if (target === "faturas") renderClientInvoices();
  if (target === "pagamentoSistema") renderPaymentSettings();
  if (target === "gestaoTerrenos") renderTerrainManagement();
  if (target === "integracaoPagamento") loadPaymentIntegration();
  if (target === "paginaInicialSite") renderHomePageSettings();
  if (target === "combustiveisConfig") renderFuelAdminSettings();
  if (target === "combustiveisPrecos") renderFuelClientPrices();
  if (target === "novidadesConfig") renderNovidadesConfig();
  if (target === "sobreNos") renderSobreNosSettings();
  if (target === "xadrezConfig") renderXadrezConfig();
  if (target === "storiesComerciais") renderStoriesComerciaisView();
  if (target === "beneficios") renderBenefitsView();
  if (target === "areaParceiro") renderPartnerBenefitsArea();
  if (target === "relatorioExclusoes") renderDeletionReport();
  if (target === "relatorioFinanceiro") renderReports("finance");
  if (target === "relatorioAcessos") {
    if (isMaster() && ["actions", "client"].includes(state.reportSection)) {
      cancelAccessReportViewLoading();
      renderReports("access");
    } else {
      const finish = beginAccessReportViewLoading();
      Promise.resolve(refreshMasterAccessMetrics())
        .then(() => {
          if (!isMaster()) renderReports("access");
        })
        .catch((error) => {
          console.error("Falha ao carregar o relatorio de acessos.", error);
          showToast("Nao foi possivel atualizar o relatorio de acessos.");
          renderReports("access");
        })
        .finally(finish);
    }
  }
  if (target === "usuariosOnline") startOnlinePresenceMonitor();
  else stopOnlinePresenceMonitor();
  if (target === "eventos") {
    configureEventAccessForProfile();
    renderEventsList();
  }
  if (target === "promocoesClientes") renderStaffPromocoesView();
  if (target === "produtosServicosClientes") renderStaffClientCatalogView();
  if (target === "noticias") renderNewsAdminList();
  if (target === "imoveis") renderImoveisList();
  if (target === "casasVeraneio") renderVacationRentalsList();
  if (target === "imoveisArtes") renderImovelArteOptions();
  if (target === "automoveis") {
    renderAutomoveisList();
  }
  if (target === "automoveisArtes") {
    renderAutomovelArteView();
  }
  if (target === "notaFalecimento" && !canManageDeathNotices()) {
    switchView(canManageClients() ? "dashboard" : "minhaEmpresa");
    return;
  }
  if (target === "gruposWhatsapp" && !canManageWhatsappGroups()) {
    switchView(canManageClients() ? "dashboard" : "minhaEmpresa");
    return;
  }
  if (target !== "clientes") setClientFocusMode(false);
}

function prepareInitialView(name) {
  const target = views[name] ? name : initialViewForProfile();
  Object.entries(views).forEach(([key, el]) => el?.classList.toggle("hidden", key !== target));
  syncAdminMenuActiveState(target);
  const [title, subtitle] = viewCopy[target] || viewCopy.dashboard;
  $("viewTitle").textContent = title;
  $("viewSubtitle").textContent = subtitle;
}

function collapseEntryFormsForView(target) {
  if (target === "beneficios" && !benefitSaveInProgress) {
    benefitFormDirty = false;
    state.selectedBenefitId = "";
    state.benefitFormOpen = false;
  }
  const formsByView = {
    clientes: ["clientForm"],
    categorias: ["categoryForm"],
    eventos: ["eventForm"],
    informacoes: ["infoDeathNoticeForm"],
    imoveis: ["imovelForm"],
    casasVeraneio: ["vacationRentalForm"],
    automoveis: ["automovelForm"],
    usuarios: ["userForm"]
  };
  (formsByView[target] || []).forEach((formId) => {
    if (formId === "clientForm") setClientFocusMode(false);
    else setFormCardOpen(formId, false);
  });
}

function setClientFocusMode(enabled) {
  const view = $("clientesView");
  const closeButton = $("closeClientFormButton");
  if (!view) return;
  view.classList.toggle("client-focus-mode", Boolean(enabled));
  closeButton?.classList.toggle("hidden", !enabled);
  setFormCardOpen("clientForm", enabled);
}

function clientSectionTitle(section) {
  return section.querySelector(".form-section-title strong, .section-head h3")?.textContent?.trim() || "Bloco do cadastro";
}

function setClientSectionExpanded(section, expanded) {
  if (!section) return;
  section.classList.toggle("is-collapsed", !expanded);
  const button = section.querySelector(":scope > .client-section-header [data-client-section-toggle]");
  button?.setAttribute("aria-expanded", expanded ? "true" : "false");
  const icon = button?.querySelector("i");
  if (icon) icon.className = expanded ? "fa-solid fa-chevron-up" : "fa-solid fa-chevron-down";
}

function setAllClientSectionsExpanded(expanded) {
  document.querySelectorAll("#clientForm > [data-client-edit-section]").forEach((section) => {
    setClientSectionExpanded(section, expanded);
  });
  if ($("clientShowAllSections")) $("clientShowAllSections").checked = expanded;
}

function addClientSectionToggle(section, header) {
  if (!section || !header || header.querySelector("[data-client-section-toggle]")) return;
  header.classList.add("client-section-header");
  const button = document.createElement("button");
  button.type = "button";
  button.className = "client-section-toggle";
  button.dataset.clientSectionToggle = "";
  button.setAttribute("aria-label", `Expandir ou retrair ${clientSectionTitle(section)}`);
  button.setAttribute("aria-expanded", "false");
  button.innerHTML = `<i class="fa-solid fa-chevron-down"></i>`;
  header.appendChild(button);
  header.addEventListener("click", (event) => {
    if (event.target.closest("input, select, textarea, a")) return;
    setClientSectionExpanded(section, section.classList.contains("is-collapsed"));
    if ($("clientShowAllSections")) {
      const sections = [...document.querySelectorAll("#clientForm > [data-client-edit-section]")];
      $("clientShowAllSections").checked = sections.length > 0 && sections.every((item) => !item.classList.contains("is-collapsed"));
    }
  });
}

function prepareClientFormSections() {
  const form = $("clientForm");
  if (!form || form.dataset.sectionsPrepared === "true") return;
  form.dataset.sectionsPrepared = "true";
  const children = [...form.children];
  const isStandaloneSection = (element) => element.matches("section.profile-upload-panel, section.upload-panel");
  const isStart = (element) => element.matches(".form-section-title") || isStandaloneSection(element);

  children.forEach((child, index) => {
    if (!isStart(child) || child.closest("[data-client-edit-section]")) return;
    if (isStandaloneSection(child)) {
      child.dataset.clientEditSection = "";
      const header = child.querySelector(":scope > .section-head");
      if (header) {
        [...child.children].filter((item) => item !== header).forEach((item) => item.classList.add("client-section-content"));
        addClientSectionToggle(child, header);
      }
      setClientSectionExpanded(child, false);
      return;
    }

    const wrapper = document.createElement("section");
    wrapper.className = "client-edit-section wide";
    wrapper.dataset.clientEditSection = "";
    form.insertBefore(wrapper, child);
    wrapper.appendChild(child);
    child.classList.add("client-section-header");
    const content = document.createElement("div");
    content.className = "client-section-body grid-form client-section-content";
    wrapper.appendChild(content);
    for (let nextIndex = index + 1; nextIndex < children.length; nextIndex += 1) {
      const next = children[nextIndex];
      if (isStart(next) || next.matches(".form-actions")) break;
      content.appendChild(next);
    }
    addClientSectionToggle(wrapper, child);
    setClientSectionExpanded(wrapper, false);
  });
}

function closeClientFormToDashboard() {
  resetClientForm();
  setClientFocusMode(false);
}

function setFormCardOpen(formId, isOpen) {
  const form = $(formId);
  const card = form?.closest(".panel-card");
  const closeButtonMap = {
    categoryForm: "closeCategoryFormButton",
    eventForm: "closeEventFormButton",
    infoDeathNoticeForm: "closeInfoDeathNoticeFormButton",
    imovelForm: "closeImovelFormButton",
    vacationRentalForm: "closeVacationRentalFormButton",
    automovelForm: "closeAutomovelFormButton",
    userForm: "closeUserFormButton"
  };
  card?.classList.toggle("form-collapsed", !isOpen);
  if (closeButtonMap[formId]) {
    $(closeButtonMap[formId])?.classList.toggle("hidden", !isOpen);
  }
}

function openFormForEdit(formId) {
  setFormCardOpen(formId, true);
  const form = $(formId);
  if (form && window.matchMedia("(max-width: 980px)").matches) {
    form.closest(".panel-card")?.scrollIntoView({ behavior: "smooth", block: "start" });
  }
}

function resetClientForm() {
  state.selectedClientId = null;
  state.clientImages = [];
  state.clientMenuImages = [];
  state.clientPromocoes = [];
  state.clientProdutos = [];
  state.clientServicos = [];
  state.clientVagas = [];
  state.clientPromoEditIndex = null;
  state.clientProductEditIndex = null;
  state.clientServiceEditIndex = null;
  $("clientForm").reset();
  delete $("clientForm").dataset.originalCategory;
  delete $("clientForm").dataset.originalClientId;
  delete $("clientForm").dataset.originalName;
  $("clientId").value = "";
  if ($("clientType")) $("clientType").value = "comercio";
  if ($("clientPaymentStatus")) $("clientPaymentStatus").value = "em_aberto";
  syncClientPaymentByType();
  if ($("clientCreci")) $("clientCreci").value = "";
  if ($("clientShortDescription")) $("clientShortDescription").value = "";
  updateClientShortDescriptionCount();
  if ($("clientCity")) $("clientCity").value = "Carlopolis - PR";
  if ($("clientImageFit")) $("clientImageFit").value = "auto";
  if ($("clientMenuEnabled")) $("clientMenuEnabled").checked = false;
  if ($("clientJobActive")) $("clientJobActive").checked = false;
  ["clientJobTitle", "clientJobDescription", "clientJobRequirements", "clientJobSalary", "clientJobSchedule", "clientJobPlace", "clientJobContact", "clientJobApply", "clientJobValidUntil"].forEach((id) => {
    if ($(id)) $(id).value = "";
  });
  fillClientCategorySelect();
  syncClientCategoryByType();
  atualizarVisibilidadeCreciCliente();
  $("deleteClientButton").classList.add("hidden");
  renderProfilePreview("clientImage", "clientProfilePreview");
  renderScheduleEditor("clientScheduleEditor", emptySchedule());
  if ($("clientOpen24Hours")) $("clientOpen24Hours").checked = false;
  toggleSchedule24Hours("clientScheduleEditor", false);
  renderClientImagesPreview();
  renderClientMenuPreview();
  renderClientPromocoesPreview();
  renderClientProdutosPreview();
  renderClientServicosPreview();
  renderMasterClientJobsPreview();
  setAllClientSectionsExpanded(false);
  setClientFocusMode(false);
}

function getClientFormData() {
  const name = $("clientName").value.trim();
  const id = $("clientId").value || slugify(name);
  const newCategory = $("clientNewCategory").value.trim();
  const currentClient = state.clientes.find((client) => client.id === state.selectedClientId);
  const tipoCliente = $("clientType")?.value || currentClient?.tipoCliente || currentClient?.tipo || "comercio";
  const category = isCategorylessClientType(tipoCliente)
    ? ""
    : (newCategory || $("clientCategory").value.trim() || currentClient?.categoria || currentClient?.category || $("clientForm").dataset.originalCategory || "Outros");
  const horarios = readScheduleEditor("clientScheduleEditor");
  const scheduleBox = $("clientScheduleEditor");
  const shouldSaveSchedule = scheduleHasAnyOpen(horarios) || scheduleBox?.dataset.initialSchedule === "true" || scheduleBox?.dataset.touchedSchedule === "true";
  const funcionamento24Horas = Boolean($("clientOpen24Hours")?.checked);
  const horarioTexto = funcionamento24Horas ? "24 horas" : (shouldSaveSchedule ? scheduleToText(horarios) : $("clientHours").value.trim());
  const contatosDetalhados = [
    { numero: $("clientContact").value.trim(), referencia: $("clientContactReference")?.value.trim() || "", whatsapp: Boolean($("clientContactIsWhatsapp")?.checked) },
    { numero: $("clientWhatsapp").value.trim(), referencia: $("clientWhatsappReference")?.value.trim() || "", whatsapp: Boolean($("clientWhatsappIsWhatsapp")?.checked) },
    { numero: $("clientContact3")?.value.trim() || "", referencia: $("clientContact3Reference")?.value.trim() || "", whatsapp: Boolean($("clientContact3IsWhatsapp")?.checked) },
    { numero: $("clientContact4")?.value.trim() || "", referencia: $("clientContact4Reference")?.value.trim() || "", whatsapp: Boolean($("clientContact4IsWhatsapp")?.checked) }
  ].filter((item) => item.numero);
  const contatos = contatosDetalhados.map((item) => item.numero);
  const whatsappPrincipal = contatosDetalhados.find((item) => item.whatsapp)?.numero || "";
  const pagamentoStatus = isBillableClientType(tipoCliente)
    ? $("clientPaymentStatus").value
    : "isento";
  return {
    id,
    nome: name,
    nomeNormalizado: normalizeName(name),
    descricaoCurta: $("clientShortDescription")?.value.trim() || "",
    categoria: category,
    categoriaId: slugify(category),
    tipoCliente,
    tipo: tipoCliente,
    status: $("clientStatus").value,
    pagamentoStatus,
    contatosDetalhados,
    contatos,
    contato: contatos[0] || "",
    whatsapp: whatsappPrincipal,
    contato2: contatos[1] || "",
    contato3: contatos[2] || "",
    creci: $("clientCreci")?.value.trim() || "",
    endereco: $("clientAddress").value.trim(),
    cidade: $("clientCity")?.value.trim() || "",
    funcionamento24Horas,
    horario: horarioTexto,
    ...(shouldSaveSchedule ? { horarios: normalizeSchedule(horarios) } : {}),
    instagram: $("clientInstagram").value.trim(),
    facebook: $("clientFacebook").value.trim(),
    tiktok: $("clientTiktok").value.trim(),
    youtube: $("clientYoutube").value.trim(),
    site: $("clientSite").value.trim(),
    imagem: $("clientImage").value.trim(),
    imagemEnquadramento: $("clientImageFit")?.value || "auto",
    imagens: normalizeImageItems(state.clientImages),
    cardapioAtivo: Boolean($("clientMenuEnabled")?.checked),
    cardapioLink: $("clientMenuLink").value.trim(),
    menuImages: normalizeUrlList(state.clientMenuImages),
    promocoes: normalizePromocoes(state.clientPromocoes),
    produtos: normalizeProdutos(state.clientProdutos),
    servicosHabilitados: Boolean($("clientServicesEnabled")?.checked),
    servicos: normalizeServicos(state.clientServicos, id),
    vagaAtiva: Boolean($("clientJobActive")?.checked),
    vagaTitulo: $("clientJobTitle")?.value.trim() || "",
    vagaCargo: $("clientJobTitle")?.value.trim() || "",
    infoVagaTrabalho: $("clientJobDescription")?.value.trim() || "",
    vagaDescricao: $("clientJobDescription")?.value.trim() || "",
    vagaPreRequisito: $("clientJobRequirements")?.value.trim() || "",
    vagaRequisitos: $("clientJobRequirements")?.value.trim() || "",
    vagaSalario: $("clientJobSalary")?.value.trim() || "",
    vagaJornada: $("clientJobSchedule")?.value.trim() || "",
    vagaLocal: $("clientJobPlace")?.value.trim() || "",
    vagaContato: $("clientJobContact")?.value.trim() || "",
    vagaComoCandidatar: $("clientJobApply")?.value.trim() || "",
    vagaValidade: $("clientJobValidUntil")?.value || "",
    infoAdicional: $("clientInfo").value.trim(),
    observacaoAdmin: $("clientAdminNote").value.trim(),
    origem: "painel",
    editadoNoPainel: true,
    updatedAt: serverTimestamp(),
    updatedBy: state.user?.uid || ""
  };
}

function imagemPrincipalNovidade(payload = {}) {
  return payload.imagem || payload.image || payload.logo || payload.imagens?.[0] || payload.menuImages?.[0] || "";
}

function tituloConteudoNovidadeAdmin(tipo, payload = {}) {
  const key = normalizeName(tipo || "");
  if (key.includes("casaveraneio")) return payload.titulo || payload.nome || "Casa de veraneio";
  if (key.includes("combustivel")) return payload.nomeExibicao || payload.razaoSocial || payload.nome || "Posto de combustível";
  if (key.includes("veiculo") || key.includes("automovel")) return [payload.marca, payload.modelo, payload.ano].filter(Boolean).join(" ") || "Veiculo";
  if (key.includes("imovel")) return payload.titulo || payload.endereco || "Imovel";
  if (key.includes("produto")) return payload.titulo || payload.nome || "Produto";
  if (key.includes("servico")) return payload.nome || payload.titulo || "Serviço";
  if (key.includes("promoc")) return payload.titulo || "Promocao";
  if (key.includes("evento")) return payload.titulo || payload.nome || "Evento";
  if (key.includes("vaga")) return payload.titulo || payload.vagaTitulo || payload.vagaCargo || "Vaga de trabalho";
  if (key.includes("grupo")) return payload.nome || payload.titulo || "Grupo WhatsApp";
  return payload.nome || payload.titulo || "";
}

function acaoNovidadeAdmin(tipo, isNew, payload = {}, original = {}) {
  const key = normalizeName(tipo || "");
  if (key.includes("casaveraneio")) return isNew ? "Casa de veraneio inserida" : "Casa de veraneio atualizada";
  if (key.includes("combustivel")) return isNew ? "Posto de combustível inserido" : "Posto de combustível atualizado";
  if (key.includes("veiculo") || key.includes("automovel")) {
    if (isNew) return "Veiculo inserido";
    const antes = numberFromMoney(original.preco || original.valor || "");
    const agora = numberFromMoney(payload.preco || payload.valor || "");
    if (antes > 0 && agora > 0 && agora < antes) return "Preco abaixou";
    if (antes > 0 && agora > 0 && agora !== antes) return "Preco atualizado";
    return "Veiculo atualizado";
  }
  if (key.includes("imovel")) {
    if (isNew) return "Imovel inserido";
    const antes = numberFromMoney(original.valor || original.preco || "");
    const agora = numberFromMoney(payload.valor || payload.preco || "");
    if (antes > 0 && agora > 0 && agora < antes) return "Preco abaixou";
    if (antes > 0 && agora > 0 && agora !== antes) return "Preco atualizado";
    return "Imovel atualizado";
  }
  if (key.includes("promoc")) {
    if (isNew) return "Promocao inserida";
    const antes = numberFromMoney(original.preco || "");
    const agora = numberFromMoney(payload.preco || "");
    if (antes > 0 && agora > 0 && agora < antes) return "Preco da promocao abaixou";
    return "Promocao atualizada";
  }
  if (key.includes("produto")) {
    if (isNew) return "Produto inserido";
    const antes = numberFromMoney(original.preco || original.valor || "");
    const agora = numberFromMoney(payload.preco || payload.valor || "");
    if (antes > 0 && agora > 0 && agora < antes) return "Preco do produto abaixou";
    if (antes > 0 && agora > 0 && agora !== antes) return "Preco do produto atualizado";
    return "Produto atualizado";
  }
  if (key.includes("servico")) {
    if (isNew) return "Serviço inserido";
    const antes = numberFromMoney(original.preco || original.valor || "");
    const agora = numberFromMoney(payload.preco || payload.valor || "");
    if (antes > 0 && agora > 0 && agora !== antes) return "Preço do serviço atualizado";
    return "Serviço atualizado";
  }
  if (key.includes("vaga")) return isNew ? "Vaga de trabalho inserida" : "Vaga de trabalho atualizada";
  if (key.includes("evento")) return isNew ? "Evento inserido" : "Evento atualizado";
  if (key.includes("grupo")) return isNew ? "Novo grupo de WhatsApp criado" : "Grupo de WhatsApp atualizado";
  return isNew ? "Cadastro novo" : "Cadastro atualizado";
}

function novidadeTopicFromPayload(payload = {}) {
  if (payload.novidadeTema && NOVIDADES_TOPICS[payload.novidadeTema]) return payload.novidadeTema;
  const tipo = normalizeName(payload.destinoTipo || payload.tipo || "");
  const acao = normalizeName(`${payload.acao || ""} ${payload.titulo || ""}`);
  if (tipo.includes("casaveraneio")) return "imovel";
  if (tipo.includes("combustivel")) return "preco";
  if (acao.includes("preco")) return "preco";
  if (tipo.includes("servico")) return "servico";
  if (tipo.includes("produto")) return "produto";
  if (tipo.includes("promoc")) return "promocao";
  if (tipo.includes("imovel")) return "imovel";
  if (tipo.includes("veiculo") || tipo.includes("automovel")) return "automovel";
  if (tipo.includes("vaga")) return "vaga";
  if (tipo.includes("evento")) return "evento";
  if (tipo.includes("grupo") || tipo.includes("whatsapp")) return "grupoWhatsapp";
  if (tipo.includes("noticia")) return "noticia";
  if (tipo.includes("endereco")) return "endereco";
  if (tipo.includes("telefone") || tipo.includes("contato")) return "telefone";
  if (tipo.includes("horario")) return "horario";
  if (tipo.includes("imagem") || acao.includes("foto")) return "imagens";
  if (tipo.includes("cardapio")) return "cardapio";
  if (tipo.includes("rede")) return "redesSociais";
  if (tipo.includes("categoria")) return "categoria";
  return "novoCliente";
}

function novidadeTopicEnabled(topic) {
  const value = state.novidadesConfig?.temas?.[topic];
  return value !== false;
}

function renderNovidadesConfig() {
  const box = $("novidadesConfigOptions");
  if (!box) return;
  box.innerHTML = Object.entries(NOVIDADES_TOPICS).map(([key, [label, description]]) => `
    <label class="novidades-config-option">
      <input type="checkbox" value="${escapeAttr(key)}" ${novidadeTopicEnabled(key) ? "checked" : ""}>
      <span><strong>${escapeHtml(label)}</strong><small>${escapeHtml(description)}</small></span>
    </label>
  `).join("");
}

function sobreNosAdminInline(text = "") {
  return escapeHtml(text).replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>");
}

function renderSobreNosAdminPreview() {
  const preview = $("sobreNosPreview");
  const input = $("sobreNosContent");
  if (!preview || !input) return;
  const content = input.value.trim();
  if ($("sobreNosCharacterCount")) $("sobreNosCharacterCount").textContent = String(input.value.length);
  if (!content) {
    preview.innerHTML = `<p class="list-meta">Digite o conteúdo para visualizar a prévia.</p>`;
    return;
  }
  const blocks = content.split(/\n\s*\n/).map((block) => block.trim()).filter(Boolean);
  preview.innerHTML = blocks.map((block, index) => {
    const isHeading = index === 0 || (block.length <= 70 && !/[.!?;:]$/.test(block) && !block.includes("\n"));
    if (index === 0) return `<h3>${sobreNosAdminInline(block.replace(/\*\*/g, ""))}</h3>`;
    if (isHeading) return `<h4>${sobreNosAdminInline(block)}</h4>`;
    return `<p>${sobreNosAdminInline(block).replace(/\n/g, "<br>")}</p>`;
  }).join("");
}

function renderSobreNosSettings() {
  const input = $("sobreNosContent");
  if (!input) return;
  input.value = String(state.sobreNos?.conteudo || DEFAULT_SOBRE_NOS_CONTENT);
  renderSobreNosAdminPreview();
}

function renderXadrezConfig() {
  if (!$("xadrezConfigForm")) return;
  const config = state.xadrezConfig || {};
  $("xadrezConfigActive").checked = config.ativo !== false;
  $("xadrezConfigName").value = config.campeonatoNome || "";
  $("xadrezConfigPrize").value = config.premio || "";
}

async function registrarNovidadeAdmin(payload = {}) {
  try {
    const actionText = normalizeName(`${payload.acao || ""} ${payload.titulo || ""} ${payload.descricao || ""}`);
    if (/(removid|excluid|desativad|retirad|ocultad|cancelad|encerrad|apagado)/.test(actionText)) return;
    const novidadeTema = novidadeTopicFromPayload(payload);
    if (!novidadeTopicEnabled(novidadeTema)) return;
    const tipo = payload.tipo || payload.destinoTipo || "estabelecimento";
    const destinoId = payload.destinoId || payload.itemId || payload.estabelecimentoId || payload.clienteId || "";
    const itemId = payload.itemId || payload.destinoCardId || "";
    await removerNovidadesPorDestino(tipo, destinoId, itemId);
    const id = `${slugify(tipo)}-${slugify(destinoId || payload.estabelecimento || payload.titulo || "item")}-${Date.now()}`;
    await update(ref(db, `novidades/${id}`), {
      tipo,
      titulo: payload.titulo || "Novidade adicionada",
      acao: payload.acao || payload.titulo || "Novidade adicionada",
      tituloConteudo: payload.tituloConteudo || payload.destinoTitulo || payload.nomeItem || "",
      descricao: payload.descricao || payload.titulo || "",
      estabelecimento: payload.estabelecimento || payload.clienteNome || "",
      imagem: payload.imagem || "",
      imagens: Array.isArray(payload.imagens) ? payload.imagens.filter(Boolean) : (payload.imagem ? [payload.imagem] : []),
      valor: payload.valor || "",
      categoria: payload.categoria || "",
      tipoCliente: payload.tipoCliente || payload.clientType || "",
      destinoTipo: payload.destinoTipo || tipo,
      destinoId,
      itemId,
      destinoCardId: payload.destinoCardId || "",
      link: payload.link || payload.url || "",
      whatsapp: payload.whatsapp || "",
      telefone: payload.telefone || payload.whatsapp || "",
      localAtendimento: payload.localAtendimento || "",
      areasAtendidas: payload.areasAtendidas || "",
      duracao: payload.duracao || "",
      prazoExecucao: payload.prazoExecucao || "",
      unidadeCobranca: payload.unidadeCobranca || "",
      observacaoPreco: payload.observacaoPreco || "",
      precisaAgendamento: Boolean(payload.precisaAgendamento),
      novidadeTema,
      dataCriacao: serverTimestamp(),
      criadoPor: payload.criadoPor || state.user?.uid || "",
      clienteId: payload.clienteId || "",
      atribuidaAoCliente: Boolean(payload.atribuidaAoCliente),
      origem: payload.origem || "painel"
    });
  } catch (error) {
    console.warn("Nao foi possivel registrar novidade.", error);
  }
}

async function registrarAtualizacoesClienteNovidade(clientId, payload = {}, original = null) {
  const effective = { ...(original || {}), ...payload };
  if (isCategorylessClientType(effective)) return;
  const profileImage = String(
    effective.imagem
    || effective.profileImage
    || effective.imagemPerfil
    || effective.perfil
    || effective.logo
    || ""
  ).trim();
  const showcaseImages = normalizeImageItems(effective.imagens)
    .map((item) => item.url)
    .filter(Boolean);
  const noveltyImages = [...new Set([profileImage, ...showcaseImages].filter(Boolean))];
  const base = {
    estabelecimento: effective.nome || clientId,
    tituloConteudo: effective.nome || clientId,
    imagem: profileImage,
    imagens: noveltyImages,
    categoria: effective.categoria || "",
    tipoCliente: effective.tipoCliente || effective.tipo || "",
    destinoTipo: "estabelecimento",
    destinoId: effective.nomeNormalizado || normalizeName(effective.nome || clientId),
    clienteId: clientId,
    criadoPor: clientId,
    atribuidaAoCliente: true,
    origem: "cliente"
  };
  if (!original) {
    await registrarNovidadeAdmin({ ...base, tipo: "estabelecimento", novidadeTema: "novoCliente", itemId: "novoCliente", titulo: "Cadastro novo", acao: "Cadastro novo", descricao: "Cadastro novo" });
    return;
  }

  const updates = [];
  const removals = [];
  const add = (tema, tipo, acao) => updates.push({ ...base, tipo, destinoTipo: tipo, novidadeTema: tema, itemId: tema, titulo: acao, acao, descricao: acao });
  const remove = (tipo, tema) => removals.push(removerNovidadesPorDestino(tipo, base.destinoId, tema));
  if (String(original.nome || "") !== String(effective.nome || "")) add("nomeCliente", "cliente-nome", "Nome do cliente atualizado");
  const originalProfileImage = String(
    original.imagem
    || original.profileImage
    || original.imagemPerfil
    || original.perfil
    || original.logo
    || ""
  ).trim();
  if (originalProfileImage !== profileImage) {
    add("logoCliente", "cliente-logo", "Logo do cliente atualizada");
    const logoUpdate = updates[updates.length - 1];
    logoUpdate.imagem = profileImage;
    logoUpdate.imagens = profileImage ? [profileImage] : [];
  }
  if (String(original.endereco || "") !== String(effective.endereco || "")) {
    if (String(effective.endereco || "").trim()) add("endereco", "cliente-endereco", "Endereço atualizado");
    else remove("cliente-endereco", "endereco");
  }
  const contactFingerprint = (client) => JSON.stringify(normalizeClientContactDetails(client).map((item) => ({
    numero: String(item.numero || "").replace(/\D/g, ""),
    referencia: String(item.referencia || "").trim(),
    whatsapp: Boolean(item.whatsapp)
  })));
  const oldPhones = contactFingerprint(original);
  const newPhones = contactFingerprint(effective);
  if (oldPhones !== newPhones) {
    if (normalizeClientContactDetails(effective).length) add("telefone", "cliente-telefone", "Telefone atualizado");
    else remove("cliente-telefone", "telefone");
  }
  const scheduleFingerprint = (client) => {
    const horarios = normalizeSchedule(client.horarios || {});
    const hasStructuredSchedule = scheduleHasAnyOpen(horarios);
    return JSON.stringify({
      funcionamento24Horas: Boolean(client.funcionamento24Horas),
      horarios: hasStructuredSchedule ? horarios : null,
      horario: hasStructuredSchedule ? "" : String(client.horario || "").replace(/\s+/g, " ").trim()
    });
  };
  const oldHours = scheduleFingerprint(original);
  const newHours = scheduleFingerprint(effective);
  if (oldHours !== newHours) {
    const hasHours = Boolean(effective.funcionamento24Horas || String(effective.horario || "").trim() || scheduleHasAnyOpen(normalizeSchedule(effective.horarios || {})));
    if (hasHours) add("horario", "cliente-horario", "Horário de atendimento atualizado");
    else remove("cliente-horario", "horario");
  }
  const originalImageUrls = new Set(normalizeImageItems(original.imagens).map((item) => item.url));
  const addedImages = normalizeImageItems(effective.imagens)
    .map((item) => item.url)
    .filter((url) => !originalImageUrls.has(url));
  if (addedImages.length) {
    add("imagens", "cliente-imagens", "Novas fotos adicionadas");
    const imagesUpdate = updates[updates.length - 1];
    imagesUpdate.imagem = addedImages[0];
    imagesUpdate.imagens = addedImages;
  }
  if (String(original.categoria || "") !== String(effective.categoria || "")) add("categoria", "cliente-categoria", "Categoria atualizada");
  const socialFingerprint = (client = {}) => JSON.stringify([
    String(client.instagram || "").trim(),
    String(client.facebook || "").trim(),
    String(client.tiktok || "").trim(),
    String(client.youtube || "").trim(),
    String(client.site || "").trim()
  ]);
  const oldSocial = socialFingerprint(original);
  const newSocial = socialFingerprint(effective);
  if (oldSocial !== newSocial) {
    if ([effective.instagram, effective.facebook, effective.tiktok, effective.youtube, effective.site].some((value) => String(value || "").trim())) add("redesSociais", "cliente-redes", "Redes sociais atualizadas");
    else remove("cliente-redes", "redesSociais");
  }
  const menuFingerprint = (client = {}) => JSON.stringify({
    ativo: Boolean(client.cardapioAtivo),
    link: String(client.cardapioLink || "").trim(),
    imagens: normalizeUrlList(client.menuImages)
  });
  const oldMenu = menuFingerprint(original);
  const newMenu = menuFingerprint(effective);
  if (oldMenu !== newMenu) {
    if (effective.cardapioAtivo || String(effective.cardapioLink || "").trim() || normalizeUrlList(effective.menuImages).length) add("cardapio", "cliente-cardapio", "Cardápio atualizado");
    else remove("cliente-cardapio", "cardapio");
  }
  const publicInfoFingerprint = (client = {}) => JSON.stringify({
    nome: String(client.nome || "").trim(),
    endereco: String(client.endereco || "").trim(),
    contatos: contactFingerprint(client),
    horarios: scheduleFingerprint(client),
    imagem: String(client.imagem || client.profileImage || client.imagemPerfil || client.perfil || client.logo || "").trim(),
    imagens: normalizeImageItems(client.imagens).map((item) => ({
      url: String(item.url || "").trim(),
      titulo: String(item.titulo || "").trim(),
      texto: String(item.texto || "").trim()
    })),
    categoria: String(client.categoria || "").trim(),
    redesSociais: socialFingerprint(client),
    cardapio: menuFingerprint(client),
    descricaoCurta: String(client.descricaoCurta || client.descricao || "").trim(),
    cidade: String(client.cidade || "").trim(),
    creci: String(client.creci || "").trim(),
    infoAdicional: String(client.infoAdicional || "").trim(),
    tipo: String(client.tipo || client.tipoCliente || "").trim(),
    status: String(client.status || "").trim(),
    imagemEnquadramento: String(client.imagemEnquadramento || "").trim(),
    vagaAtiva: Boolean(client.vagaAtiva),
    vagaTitulo: String(client.vagaTitulo || client.vagaCargo || "").trim(),
    vagaDescricao: String(client.vagaDescricao || client.infoVagaTrabalho || "").trim(),
    vagaRequisitos: String(client.vagaRequisitos || client.vagaPreRequisito || "").trim(),
    vagaSalario: String(client.vagaSalario || "").trim(),
    vagaJornada: String(client.vagaJornada || "").trim(),
    vagaLocal: String(client.vagaLocal || "").trim(),
    vagaContato: String(client.vagaContato || "").trim(),
    vagaComoCandidatar: String(client.vagaComoCandidatar || "").trim(),
    vagaValidade: String(client.vagaValidade || "").trim()
  });
  const generalInfoFingerprint = (client = {}) => JSON.stringify({
    descricaoCurta: String(client.descricaoCurta || client.descricao || "").trim(),
    cidade: String(client.cidade || "").trim(),
    creci: String(client.creci || "").trim(),
    infoAdicional: String(client.infoAdicional || "").trim(),
    tipo: String(client.tipo || client.tipoCliente || "").trim(),
    status: String(client.status || "").trim(),
    imagemEnquadramento: String(client.imagemEnquadramento || "").trim(),
    vagaAtiva: Boolean(client.vagaAtiva),
    vagaTitulo: String(client.vagaTitulo || client.vagaCargo || "").trim(),
    vagaDescricao: String(client.vagaDescricao || client.infoVagaTrabalho || "").trim(),
    vagaRequisitos: String(client.vagaRequisitos || client.vagaPreRequisito || "").trim(),
    vagaSalario: String(client.vagaSalario || "").trim(),
    vagaJornada: String(client.vagaJornada || "").trim(),
    vagaLocal: String(client.vagaLocal || "").trim(),
    vagaContato: String(client.vagaContato || "").trim(),
    vagaComoCandidatar: String(client.vagaComoCandidatar || "").trim(),
    vagaValidade: String(client.vagaValidade || "").trim()
  });
  const generalInfoChanged = generalInfoFingerprint(original) !== generalInfoFingerprint(effective);
  if (generalInfoChanged) {
    add("dadosCliente", "cliente-dados", "Informações Atualizadas");
  } else if (!updates.length && publicInfoFingerprint(original) !== publicInfoFingerprint(effective)) {
    add("dadosCliente", "cliente-dados", "Informações Atualizadas");
  }
  await Promise.all([...removals, ...updates.map(registrarNovidadeAdmin)]);
}

async function removerNovidadesPorDestino(tipo, destinoId, itemId = "") {
  try {
    const snap = await get(ref(db, "novidades"));
    if (!snap.exists()) return;
    const tipoNorm = normalizeName(tipo || "");
    const destino = String(destinoId || "");
    const item = String(itemId || "");
    const updates = {};
    snap.forEach((child) => {
      const novidade = child.val() || {};
      const novidadeTipo = normalizeName(novidade.destinoTipo || novidade.tipo || "");
      const mesmoTipo = !tipoNorm || novidadeTipo.includes(tipoNorm) || tipoNorm.includes(novidadeTipo);
      const mesmoDestino = destino && String(novidade.destinoId || "") === destino;
      const novidadeItemId = String(novidade.itemId || "");
      const novidadeCardId = String(novidade.destinoCardId || "");
      const novidadeId = String(novidade.id || child.key || "");
      const mesmoItem = Boolean(item) && (
        novidadeItemId === item ||
        (novidadeCardId && novidadeCardId.includes(item)) ||
        (novidadeItemId && item.includes(novidadeItemId)) ||
        (novidadeCardId && item.includes(novidadeCardId)) ||
        (novidadeId && novidadeId.includes(item))
      );
      const mesmoAlvo = destino ? mesmoDestino : true;
      if (mesmoTipo && mesmoAlvo && (mesmoItem || (!item && mesmoDestino))) updates[`novidades/${child.key}`] = null;
      return false;
    });
    if (Object.keys(updates).length) await update(ref(db), updates);
  } catch (error) {
    console.warn("Nao foi possivel remover novidades antigas.", error);
  }
}

