function renderAutomovelImagesPreview() {
  const box = $("automovelImagesPreview");
  if (!box) return;
  const coverInput = $("automovelImagem");
  if (coverInput && state.automovelImages.length && !state.automovelImages.includes(coverInput.value.trim())) coverInput.value = state.automovelImages[0];
  if (coverInput && !state.automovelImages.length) coverInput.value = "";
  const cover = $("automovelImagem")?.value.trim() || state.automovelImages[0] || "";
  $("automovelImagesCount").textContent = `${state.automovelImages.length} imagen${state.automovelImages.length === 1 ? "" : "s"}`;
  box.innerHTML = state.automovelImages.map((url, index) => `
    <article class="${url === cover ? "is-cover" : ""}" data-reorder-auto-image="${index}" data-auto-image-url="${escapeAttr(url)}" title="Arraste para mudar a ordem">
      <span class="auto-image-order-badge">${index + 1}</span>
      <img src="${escapeAttr(displayImageUrl(url))}" alt="Foto ${index + 1}" draggable="false" ${lazyImageAttrs()} ${imageFallbackAttr()}>
      <button type="button" class="cover-button" data-cover-auto-image="${index}">${url === cover ? "Capa atual" : "Usar como capa"}</button>
      <button type="button" data-remove-auto-image="${index}">Remover</button>
    </article>
  `).join("") || `<div class="list-meta">Nenhuma foto adicionada.</div>`;
  let dragState = null;
  const HOLD_DRAG_AUTOMOVEL_IMAGE_MS = 320;
  const MOVE_CANCEL_AUTOMOVEL_IMAGE_PX = 10;
  const reorderImage = (fromIndex, toIndex, renderAfter = true) => {
    if (fromIndex === toIndex || fromIndex < 0 || toIndex < 0 || fromIndex >= state.automovelImages.length || toIndex >= state.automovelImages.length) return;
    const [url] = state.automovelImages.splice(fromIndex, 1);
    state.automovelImages.splice(toIndex, 0, url);
    if (renderAfter) renderAutomovelImagesPreview();
  };
  const sincronizarAutomovelImagesPreview = () => {
    const coverAtual = $("automovelImagem")?.value.trim() || state.automovelImages[0] || "";
    if ($("automovelImagem") && !($("automovelImagem").value || "").trim() && coverAtual) $("automovelImagem").value = coverAtual;
    box.querySelectorAll("[data-reorder-auto-image]").forEach((article, index) => {
      const isCover = article.dataset.autoImageUrl === coverAtual;
      article.dataset.reorderAutoImage = String(index);
      article.classList.toggle("is-cover", isCover);
      const badge = article.querySelector(".auto-image-order-badge");
      if (badge) badge.textContent = String(index + 1);
      const coverButton = article.querySelector("[data-cover-auto-image]");
      if (coverButton) {
        coverButton.dataset.coverAutoImage = String(index);
        coverButton.textContent = isCover ? "Capa atual" : "Usar como capa";
      }
      const removeButton = article.querySelector("[data-remove-auto-image]");
      if (removeButton) removeButton.dataset.removeAutoImage = String(index);
    });
  };
  const moverAutomovelImageCardNoDom = (card, fromIndex, toIndex) => {
    if (!card || fromIndex === toIndex) return;
    const target = [...box.querySelectorAll("[data-reorder-auto-image]")][toIndex];
    if (!target || target === card) return;
    if (fromIndex < toIndex) box.insertBefore(card, target.nextSibling);
    else box.insertBefore(card, target);
    sincronizarAutomovelImagesPreview();
  };
  const limparArrasteAutomovelImages = () => {
    if (!dragState) return;
    if (dragState.holdTimer) clearTimeout(dragState.holdTimer);
    if (dragState.frame) cancelAnimationFrame(dragState.frame);
    (dragState.cards || [dragState.card]).forEach((card) => {
      card.classList.remove("is-dragging", "is-shifting");
      card.style.transform = "";
      card.style.transition = "";
    });
    dragState.card?.classList.remove("is-hold-pending");
    box.classList.remove("is-reordering");
    document.body.classList.remove("admin-auto-image-dragging");
  };
  const indiceAutomovelImagePorPonto = (x, y) => {
    if (!dragState?.active || !dragState.rects?.length) return -1;
    let melhorIndice = dragState.startIndex;
    let melhorDistancia = Infinity;
    dragState.rects.forEach((rect, index) => {
      const dentroX = x >= rect.left && x <= rect.right;
      const dentroY = y >= rect.top && y <= rect.bottom;
      if (dentroX && dentroY) {
        melhorIndice = index;
        melhorDistancia = -1;
        return;
      }
      if (melhorDistancia < 0) return;
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const distancia = Math.hypot(x - cx, y - cy);
      if (distancia < melhorDistancia) {
        melhorDistancia = distancia;
        melhorIndice = index;
      }
    });
    return melhorIndice;
  };
  const aplicarArrasteAutomovelImages = () => {
    if (!dragState?.active) return;
    dragState.frame = null;
    const dxDrag = dragState.lastX - dragState.startX;
    const dyDrag = dragState.lastY - dragState.startY;
    const start = dragState.startIndex;
    const target = dragState.targetIndex;
    dragState.cards.forEach((card, index) => {
      if (card === dragState.card) {
        card.style.transform = `translate(${dxDrag}px, ${dyDrag}px) scale(.96)`;
        return;
      }
      let destino = null;
      if (target > start && index > start && index <= target) destino = dragState.rects[index - 1];
      if (target < start && index >= target && index < start) destino = dragState.rects[index + 1];
      if (!destino) {
        card.classList.remove("is-shifting");
        card.style.transform = "";
        return;
      }
      const atual = dragState.rects[index];
      card.classList.add("is-shifting");
      card.style.transform = `translate(${destino.left - atual.left}px, ${destino.top - atual.top}px)`;
    });
  };
  const agendarArrasteAutomovelImages = () => {
    if (!dragState?.active || dragState.frame) return;
    dragState.frame = requestAnimationFrame(aplicarArrasteAutomovelImages);
  };
  const ativarArrasteAutomovelImages = () => {
    if (!dragState || dragState.active) return;
    const cards = [...box.querySelectorAll("[data-reorder-auto-image]")];
    const startIndex = Number(dragState.card.dataset.reorderAutoImage);
    dragState.active = true;
    dragState.cards = cards;
    dragState.rects = cards.map((card) => card.getBoundingClientRect());
    dragState.startIndex = startIndex;
    dragState.targetIndex = startIndex;
    dragState.frame = null;
    dragState.card.classList.remove("is-hold-pending");
    dragState.card.classList.add("is-dragging");
    box.classList.add("is-reordering");
    document.body.classList.add("admin-auto-image-dragging");
    dragState.card.setPointerCapture?.(dragState.pointerId);
    agendarArrasteAutomovelImages();
  };
  const cancelarArrasteAutomovelImages = (event) => {
    if (!dragState || (event?.pointerId !== undefined && event.pointerId !== dragState.pointerId)) return;
    limparArrasteAutomovelImages();
    dragState = null;
  };
  const finishAutomovelImageDrag = (event, shouldRender = true) => {
    if (!dragState || (event?.pointerId !== undefined && event.pointerId !== dragState.pointerId)) return;
    if (!dragState.active) {
      cancelarArrasteAutomovelImages(event);
      return;
    }
    const { card, pointerId, startIndex, targetIndex } = dragState;
    card.releasePointerCapture?.(pointerId);
    limparArrasteAutomovelImages();
    dragState = null;
    if (targetIndex !== startIndex) {
      reorderImage(startIndex, targetIndex, false);
      if (shouldRender) moverAutomovelImageCardNoDom(card, startIndex, targetIndex);
    }
  };
  box.querySelectorAll("[data-reorder-auto-image]").forEach((article) => {
    article.addEventListener("contextmenu", (event) => {
      if (dragState?.card === article) event.preventDefault();
    });
    article.addEventListener("pointerdown", (event) => {
      if (event.target.closest("button")) return;
      cancelarArrasteAutomovelImages();
      dragState = {
        pointerId: event.pointerId,
        card: article,
        active: false,
        startX: event.clientX,
        startY: event.clientY,
        lastX: event.clientX,
        lastY: event.clientY,
        holdTimer: event.pointerType === "mouse" ? null : window.setTimeout(ativarArrasteAutomovelImages, HOLD_DRAG_AUTOMOVEL_IMAGE_MS)
      };
      if (event.pointerType === "mouse") {
        event.preventDefault();
        ativarArrasteAutomovelImages();
      } else {
        article.classList.add("is-hold-pending");
      }
    });
    article.addEventListener("pointermove", (event) => {
      if (!dragState || event.pointerId !== dragState.pointerId) return;
      if (!dragState.active) {
        if (Math.hypot(event.clientX - dragState.startX, event.clientY - dragState.startY) > MOVE_CANCEL_AUTOMOVEL_IMAGE_PX) {
          cancelarArrasteAutomovelImages(event);
        }
        return;
      }
      event.preventDefault();
      dragState.lastX = event.clientX;
      dragState.lastY = event.clientY;
      const novoIndice = indiceAutomovelImagePorPonto(event.clientX, event.clientY);
      if (novoIndice >= 0) dragState.targetIndex = novoIndice;
      agendarArrasteAutomovelImages();
    });
    article.addEventListener("pointerup", (event) => {
      finishAutomovelImageDrag(event);
    });
    article.addEventListener("pointercancel", (event) => {
      finishAutomovelImageDrag(event);
    });
  });
  box.querySelectorAll("[data-cover-auto-image]").forEach((button) => {
    button.addEventListener("click", () => {
      const url = state.automovelImages[Number(button.dataset.coverAutoImage)] || "";
      if ($("automovelImagem")) $("automovelImagem").value = url;
      renderAutomovelImagesPreview();
    });
  });
  box.querySelectorAll("[data-remove-auto-image]").forEach((button) => {
    button.addEventListener("click", () => {
      state.automovelImages.splice(Number(button.dataset.removeAutoImage), 1);
      if (!state.automovelImages.includes($("automovelImagem").value)) $("automovelImagem").value = state.automovelImages[0] || "";
      renderAutomovelImagesPreview();
    });
  });
}

