  if ($("newsDate")) $("newsDate").value = publicationClock.date;
  if ($("newsTime")) $("newsTime").value = publicationClock.time;
  if ($("newsShowHome")) $("newsShowHome").checked = true;
  state.noticiaExtraImages = [];
