function buildAccessTimeline(acessos = {}, range = getReportDateRange()) {
  const rows = [];
  Object.entries(acessos || {}).forEach(([date, dia]) => {
    if (date < range.start || date > range.end) return;
    Object.values(dia?.detalhados || {}).forEach((item) => {
      rows.push({
        date,
        hora: formatReportTime(item, date),
        origem: origemLabel(item?.origem || item?.canal || item?.referrer),
        canal: item?.canal || "-",
        cidade: [item?.cidade || "Desconhecida", item?.estado || ""].filter(Boolean).join(" - "),
        dispositivo: item?.dispositivo || "-",
        pagina: item?.pagina || ""
      });
    });
  });
  return rows.sort((a, b) => `${b.date} ${b.hora}`.localeCompare(`${a.date} ${a.hora}`));
}

function clientMetricKeys(client = {}) {
  const values = [
    client.id,
    client.nome,
    client.name,
    client.nomeNormalizado,
    client.estabelecimentoId,
    clientCanonicalId(client),
    ...(client.aliases ? Object.keys(client.aliases) : [])
  ];
  return [...new Set(values.flatMap(aliasKeyVariants).map((value) => normalizeName(value)).filter(Boolean))];
}

function metricKeyBelongsToClient(metricKey, keys = []) {
  const key = normalizeName(metricKey);
  if (!key) return false;
  return keys.some((candidate) => {
    if (!candidate) return false;
    if (key === candidate) return true;
    return candidate.length > 4 && (key.includes(candidate) || candidate.includes(key));
  });
}

function sumMetricMapForClient(map = new Map(), keys = []) {
  let total = 0;
  map.forEach((count, key) => {
    if (metricKeyBelongsToClient(key, keys)) total += Number(count || 0);
  });
  return total;
}

function aggregateButtonTypesForClient(details = new Map(), keys = []) {
  const tipos = new Map();
  details.forEach((typeMap, clientKey) => {
    if (!metricKeyBelongsToClient(clientKey, keys)) return;
    typeMap.forEach((count, type) => incrementMetric(tipos, type, count));
  });
  return tipos;
}

function clientReportCategory(row = {}) {
  const text = normalizeName(`${row.area || ""} ${row.tipo || ""}`);
  if (/casaveraneio|casasveraneio/.test(text)) return "Casas de veraneio";
  if (/novidade|novidades/.test(text)) return "Novidades";
  if (/servico/.test(text)) return "Servicos";
  if (/imovel/.test(text)) return "Imoveis";
  if (/veiculo|automovel/.test(text)) return "Veiculos";
  if (/perfil/.test(text)) return "Visualizacao do perfil";
  if (/destaque/.test(text)) return "Destaques";
  if (/compartilh/.test(text)) return "Compartilhamentos";
  if (/grupowhatsapp|grupowhats|grupozap/.test(text)) return "Grupo WhatsApp";
  if (/whatsapppromocao/.test(text)) return "WhatsApp da promocao";
  if (/whatsapp|telefone|contato|zap/.test(text)) return "WhatsApp / telefone";
  if (/cardapio|menu/.test(text)) return "Cardapio";
  if (/foto|fotos|imagem|divulgacao/.test(text)) return "Fotos / divulgacao";
  if (/instagrampromocao/.test(text)) return "Redes sociais / links";
  if (/promocao|promocoes|oferta/.test(text)) return "Promocoes";
  if (/instagram|facebook|tiktok|youtube|site|rede|social|link/.test(text)) return "Redes sociais / links";
  return row.tipo || row.area || "Clique";
}

function clientPageTimelineResourceKey(row = {}) {
  const identity = normalizeName(`${row.tipo || ""} ${row.area || ""} ${row.categoria || ""}`);
  if (/perfil|acessopagina/.test(identity)) return "perfil";
  if (/grupowhatsapp|grupowhats|grupozap/.test(identity)) return "gruposWhatsapp";
  if (/whatsapp|telefone|contato|zap/.test(identity)) return "whats";
  if (/foto|imagem|divulgacao/.test(identity)) return "fotos";
  if (/novidade/.test(identity)) return "novidades";
  if (/compartilh/.test(identity)) return "compartilhamentos";
  if (/destaque/.test(identity)) return "destaques";
  if (/instagram/.test(identity)) return "instagram";
  if (/facebook/.test(identity)) return "facebook";
  if (/tiktok/.test(identity)) return "tiktok";
  if (/youtube/.test(identity)) return "youtube";
  if (/site/.test(identity)) return "site";
  if (/rede|social|link/.test(identity)) return "outrasRedes";
  return "outros";
}

function clientReportMenuEnabled(client = currentClientRecord() || {}) {
  return Boolean(
    client.cardapioAtivo
    || client.menuAtivo
    || client.exibirCardapio
    || client.cardapioLink
    || normalizeUrlList(client.menuImages).length
  );
}

function clientReportOndeComerEnabled(client = {}) {
  const category = normalizeName(client.categoria || client.category || client.categoriaId || "");
  return /acai|lanchonete|padaria|pizzaria|restaurante|sorveteria/.test(category);
}

function clientReportPermissions(client = currentClientRecord() || {}) {
  if (!canManageClients()) return state.profile?.permissoes || {};
  const permissions = { ...(client.permissoes || {}) };
  (state.usuarios || [])
    .filter((user) => String(user.clienteId || "") === String(client.id || ""))
    .forEach((user) => Object.entries(user.permissoes || {}).forEach(([key, enabled]) => {
      if (enabled === true) permissions[key] = true;
    }));
  return permissions;
}

function clientReportHasPermission(client = {}, permission = "") {
  return Boolean(clientReportPermissions(client)[permission]);
}

function clientReportHasPublicProfile(client = {}) {
  const category = String(client.categoria || client.category || client.categoriaId || "").trim();
  const status = normalizeName(client.status || "ativo");
  const explicitlyHidden = client.paginaPublicaAtiva === false
    || client.exibirNoSite === false
    || client.visivelNoSite === false;
  return Boolean(category)
    && !isCategorylessClientType(client)
    && !explicitlyHidden
    && !["inativo", "inativa", "inactive"].includes(status);
}

function clientReportResourceAllowed(category = "", client = currentClientRecord() || {}) {
  const normalized = normalizeName(category);
  if (/casaveraneio|casasveraneio/.test(normalized)) return clientReportHasPermission(client, "casas_veraneio");
  if (/imovel/.test(normalized)) return clientReportHasPermission(client, "imoveis") || clienteAssociadoImoveis(client);
  if (/veiculo|automovel/.test(normalized)) return clientReportHasPermission(client, "veiculos") || clienteAssociadoAutomoveis(client);
  if (/cardapio/.test(normalized)) return clientReportHasPermission(client, "cardapio") || clientReportMenuEnabled(client);
  if (/novidade/.test(normalized)) return true;
  if (/promoc/.test(normalized)) return clientReportHasPermission(client, "promocoes");
  if (/produto/.test(normalized)) return clientReportHasPermission(client, "produtos");
  if (/servico/.test(normalized)) return clientReportHasPermission(client, "servicos");
  if (/foto|divulgacao|imagem/.test(normalized)) return clientReportHasPermission(client, "imagens") || clientReportHasPermission(client, "destaque");
  return true;
}

