function renderPaymentSettings() {
  if (!$("paymentSettingsForm")) return;
  const config = state.pagamentoSistema || {};
  $("paymentPixKey").value = config.pixChave || "";
  $("paymentPixName").value = config.pixNome || "Ola Carlopolis";
  $("paymentPixCity").value = config.pixCidade || "CARLOPOLIS";
  $("paymentBillingWhatsapp").value = formatPhoneMask(config.whatsappCobranca || "43991766639");
  $("paymentDefaultDueDay").value = config.vencimentoDiaPadrao || "";
  $("paymentInvoiceLogo").value = config.logoBoleto || "";
  $("paymentInvoiceLogoPreview").src = boletoLogoUrl(config);
  $("paymentPlanMonthly").value = config.valorPlanoMensal ? moneyBR(config.valorPlanoMensal) : "";
  $("paymentPlanSemiannual").value = config.valorPlanoSemestral ? moneyBR(config.valorPlanoSemestral) : "";
  $("paymentPlanAnnual").value = config.valorPlanoAnual ? moneyBR(config.valorPlanoAnual) : "";
  if ($("paymentNewsVisibleDays")) $("paymentNewsVisibleDays").value = config.diasNovidadesVisiveis || 5;
  $("paymentInvoiceNote").value = config.observacaoFatura || "";
  $("paymentInvoiceFooterMessage").value = config.mensagemRodapeBoleto || "";
}

async function paymentIntegrationRequest(path = "/api/payment-integration", payload = null) {
  if (!state.user) throw new Error("Sessão não identificada.");
  const token = await state.user.getIdToken();
  const response = await fetch(path, {
    method: payload ? "POST" : "GET",
    headers: { accept: "application/json", authorization: `Bearer ${token}`, ...(payload ? { "content-type": "application/json" } : {}) },
    body: payload ? JSON.stringify(payload) : undefined,
    cache: "no-store"
  });
  const result = await response.json().catch(() => ({}));
  if (!response.ok || result.success === false) throw new Error(result.message || `Falha no servidor (HTTP ${response.status}).`);
  return result;
}

function paymentProviderLabel(provider) {
  return { mercadopago: "Mercado Pago", asaas: "Asaas", generic: "Webhook personalizado", finance: "Financeiro atual" }[provider] || "Não configurado";
}

function renderPaymentIntegrationReport() {
  const integration = state.integracaoPagamento || {};
  const config = integration.config || {};
  const integrationCharges = Array.isArray(integration.charges) ? integration.charges : [];
  const chargedClients = new Set(integrationCharges.map((item) => item.clientId).filter(Boolean));
  const financeRows = state.clientes
    .filter((client) => isBillableClientType(client) && effectivePaymentStatus(client) !== "isento" && !chargedClients.has(client.id))
    .map((client) => {
      const status = effectivePaymentStatus(client) === "pago" ? "paid" : "pending";
      return {
        clientId: client.id,
        clientName: client.nome || client.id,
        months: status === "paid" ? [financePaidReferenceMonth(client)].filter(Boolean) : pendingMonthsForClient(client),
        amount: valorTotalFaturaCliente(client),
        provider: "finance",
        status,
        updatedAt: client.updatedAt || 0
      };
    });
  const charges = [...integrationCharges, ...financeRows];
  const events = Array.isArray(integration.events) ? integration.events : [];
  const paid = charges.filter((item) => item.status === "paid");
  const pending = charges.filter((item) => item.status !== "paid");
  const errors = events.filter((item) => item.status === "error" || item.status === "unmatched");
  if ($("paymentIntegrationStatus")) $("paymentIntegrationStatus").textContent = config.enabled ? "Ativa" : "Desativada";
  if ($("paymentIntegrationStatusDetail")) $("paymentIntegrationStatusDetail").textContent = config.enabled
    ? `${paymentProviderLabel(config.provider)} · ${config.environment === "sandbox" ? "Teste" : "Produção"}`
    : "O PIX atual continua funcionando normalmente.";
  if ($("paymentIntegrationPaidCount")) $("paymentIntegrationPaidCount").textContent = String(paid.length);
  if ($("paymentIntegrationPendingCount")) $("paymentIntegrationPendingCount").textContent = String(pending.length);
  if ($("paymentIntegrationErrorCount")) $("paymentIntegrationErrorCount").textContent = String(errors.length);
  const filter = $("paymentIntegrationReportFilter")?.value || "all";
  const visible = charges.filter((item) => filter === "all" || (filter === "paid" ? item.status === "paid" : item.status !== "paid"));
  const mount = $("paymentIntegrationReport");
  if (!mount) return;
  if (!visible.length) {
    mount.innerHTML = `<div class="payment-integration-empty"><i class="fa-solid fa-receipt"></i><strong>Nenhuma cobrança neste filtro</strong><span>As cobranças aparecerão aqui quando um cliente gerar o PIX.</span></div>`;
    return;
  }
  mount.innerHTML = `
    <div class="payment-integration-table-wrap">
      <table class="payment-integration-table">
        <thead><tr><th>Cliente</th><th>Referência</th><th>Valor</th><th>Provedor</th><th>Situação</th><th>Atualização</th></tr></thead>
        <tbody>${visible.map((item) => `
          <tr>
            <td><strong>${escapeHtml(item.clientName || item.clientId || "Cliente")}</strong><small>${escapeHtml((item.months || []).map(monthLabel).join(", "))}</small></td>
            <td><code>${escapeHtml(item.txid || "-")}</code><small>${escapeHtml(item.providerPaymentId || "")}</small></td>
            <td>${moneyBR(item.amount)}</td>
            <td>${escapeHtml(paymentProviderLabel(item.provider))}</td>
            <td><span class="badge ${item.status === "paid" ? "pago" : "em_aberto"}">${item.status === "paid" ? "Pago" : "Pendente"}</span></td>
            <td>${item.updatedAt ? escapeHtml(new Date(item.updatedAt).toLocaleString("pt-BR")) : "-"}</td>
          </tr>`).join("")}
        </tbody>
      </table>
    </div>`;
}

function fillPaymentIntegrationForm() {
  const config = state.integracaoPagamento?.config || {};
  if (!$("paymentIntegrationForm")) return;
  $("paymentIntegrationEnabled").checked = config.enabled === true;
  $("paymentIntegrationProvider").value = config.provider || "mercadopago";
  $("paymentIntegrationEnvironment").value = config.environment || "sandbox";
  $("paymentIntegrationAccessToken").value = "";
  $("paymentIntegrationWebhookSecret").value = "";
  $("paymentIntegrationAccessTokenState").textContent = config.accessTokenConfigured ? "Token protegido já salvo no servidor." : "Nenhum token salvo.";
  $("paymentIntegrationWebhookSecretState").textContent = config.webhookSecretConfigured ? "Segredo protegido já salvo no servidor." : "Nenhum segredo salvo.";
  $("paymentIntegrationWebhookUrl").value = `${window.location.origin}/api/payment-webhook`;
  $("paymentIntegrationTokenHeader").value = config.webhookTokenHeader || "x-payment-token";
  $("paymentIntegrationTxidField").value = config.txidField || "txid";
  $("paymentIntegrationStatusField").value = config.statusField || "status";
  $("paymentIntegrationTransactionField").value = config.transactionIdField || "transactionId";
  $("paymentIntegrationAmountField").value = config.amountField || "amount";
  $("paymentIntegrationPaidStatuses").value = config.paidStatuses || "paid,approved,confirmed,received";
  $("paymentIntegrationAdvanced").classList.toggle("hidden", $("paymentIntegrationProvider").value !== "generic");
}

async function loadPaymentIntegration(force = false) {
  if (!isMaster() || (!force && state.integracaoPagamento?.loading)) return;
  state.integracaoPagamento.loading = true;
  if ($("paymentIntegrationReport")) $("paymentIntegrationReport").innerHTML = `<div class="list-meta">Carregando integração e relatório...</div>`;
  try {
    const result = await paymentIntegrationRequest();
    state.integracaoPagamento = { config: result.config || {}, charges: result.charges || [], events: result.events || [], loaded: true, loading: false };
    fillPaymentIntegrationForm();
    renderPaymentIntegrationReport();
    startPaymentIntegrationRealtime();
  } catch (error) {
    state.integracaoPagamento.loading = false;
    if ($("paymentIntegrationReport")) $("paymentIntegrationReport").innerHTML = `<div class="payment-integration-error">${escapeHtml(error.message)}</div>`;
    showToast(error.message || "Não foi possível carregar a integração.");
  }
}

function stopPaymentIntegrationRealtime() {
  if (paymentIntegrationRealtimeUnsubscribe) paymentIntegrationRealtimeUnsubscribe();
  paymentIntegrationRealtimeUnsubscribe = null;
}

function startPaymentIntegrationRealtime() {
  stopPaymentIntegrationRealtime();
  if (!isMaster()) return;
  paymentIntegrationRealtimeUnsubscribe = onValue(ref(db, "pagamentosIntegracao"), (snapshot) => {
    const value = snapshot.exists() ? snapshot.val() : {};
    state.integracaoPagamento.charges = Object.values(value.cobrancas || {}).sort((a, b) => Number(b.updatedAt || 0) - Number(a.updatedAt || 0));
    state.integracaoPagamento.events = Object.entries(value.eventos || {}).map(([id, item]) => ({ id, ...item })).sort((a, b) => Number(b.createdAt || 0) - Number(a.createdAt || 0));
    renderPaymentIntegrationReport();
  }, (error) => console.warn("Falha ao acompanhar pagamentos em tempo real.", error));
}

async function savePaymentIntegration(event) {
  event.preventDefault();
  if (!isMaster()) return;
  const button = event.submitter;
  setBusy(button, true, "Salvando...");
  try {
    const result = await paymentIntegrationRequest("/api/payment-integration", {
      action: "save",
      config: {
        enabled: $("paymentIntegrationEnabled").checked,
        provider: $("paymentIntegrationProvider").value,
        environment: $("paymentIntegrationEnvironment").value,
        webhookTokenHeader: $("paymentIntegrationTokenHeader").value,
        txidField: $("paymentIntegrationTxidField").value,
        statusField: $("paymentIntegrationStatusField").value,
        transactionIdField: $("paymentIntegrationTransactionField").value,
        amountField: $("paymentIntegrationAmountField").value,
        paidStatuses: $("paymentIntegrationPaidStatuses").value
      },
      secrets: {
        accessToken: $("paymentIntegrationAccessToken").value,
        webhookSecret: $("paymentIntegrationWebhookSecret").value
      }
    });
    state.integracaoPagamento.config = result.config || {};
    fillPaymentIntegrationForm();
    renderPaymentIntegrationReport();
    showToast(result.message || "Integração salva.");
  } catch (error) {
    showToast(error.message || "Falha ao salvar a integração.");
  } finally {
    setBusy(button, false);
  }
}

async function testPaymentIntegration(button) {
  setBusy(button, true, "Testando...");
  try {
    const result = await paymentIntegrationRequest("/api/payment-integration", { action: "test" });
    showToast(result.message || "Conexão confirmada.");
  } catch (error) {
    showToast(error.message || "A conexão não foi confirmada.");
  } finally {
    setBusy(button, false);
  }
}

async function createIntegratedPaymentCharge(client, invoice, months = [], planType = "mensal") {
  if (!client?.id || !invoice?.txid || !invoice?.valorTotal || !months.length) return { mode: "static" };
  try {
    return await paymentIntegrationRequest("/api/payment-charge", {
      clientId: client.id,
      txid: invoice.txid,
      amount: invoice.valorTotal,
      months,
      planType
    });
  } catch (error) {
    console.error("Integração automática indisponível; mantendo o PIX atual.", error);
    showToast("PIX atual gerado. A confirmação automática não respondeu e deve ser conferida.");
    return { mode: "static", integrationError: true };
  }
}

async function uploadPaymentInvoiceLogo(file) {
  if (!file || !isMaster()) return;
  const extension = String(file.name || "logo.png").split(".").pop() || "png";
  const path = `configuracoes/pagamento/logo-boleto-${Date.now()}.${slugify(extension)}`;
  const fileRef = storageRef(storage, path);
  const url = await uploadFileWithProgress(fileRef, file, "Enviando logo dos boletos", file.name || "logo");
  $("paymentInvoiceLogo").value = url;
  $("paymentInvoiceLogoPreview").src = displayImageUrl(url);
  showToast("Logo enviada. Clique em Salvar pagamento para confirmar.");
}

function fuelAdminStationMap() {
  const postos = state.combustiveisConfig?.postos;
  return postos && typeof postos === "object" ? { ...postos } : {};
}

function fuelAdminProductMap(station) {
  const produtos = station?.combustiveis;
  if (produtos && typeof produtos === "object") return { ...produtos };
  return {};
}

function fuelAdminStationUpdateUrl(stationId, access = {}) {
  if (!stationId || !access.email || !access.password) return "";
  const pageUrl = new URL("../atualizar-combustivel.html", window.location.href);
  pageUrl.hash = new URLSearchParams({ posto: stationId, email: access.email, chave: access.password }).toString();
  return pageUrl.href;
}

function fuelAdminSecureToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function renderFuelAdminLinkBox(stationId) {
  const access = state.combustiveisLinks?.[stationId] || {};
  const active = access.ativo === true && Boolean(access.email && access.password && access.uid);
  const link = active ? fuelAdminStationUpdateUrl(stationId, access) : "";
  return `<section class="fuel-admin-link-box">
    <div class="fuel-admin-link-head"><div><strong><i class="fa-solid fa-link"></i> Link para o responsavel do posto</strong><small> Exclusivo, revogavel e sem necessidade de login.</small></div><span class="badge ${active ? "ativo" : "inativo"}">${active ? "Ativo" : "Nao gerado"}</span></div>
    <div class="fuel-admin-link-controls">
      <input data-fuel-update-link readonly value="${escapeAttr(link)}" placeholder="Clique em Gerar link">
      <button class="primary" type="button" data-generate-fuel-link="${escapeAttr(stationId)}"><i class="fa-solid fa-wand-magic-sparkles"></i> ${active ? "Gerar novo" : "Gerar link"}</button>
      <button type="button" data-copy-fuel-link="${escapeAttr(stationId)}" ${active ? "" : "disabled"}><i class="fa-solid fa-copy"></i> Copiar</button>
      <button type="button" data-revoke-fuel-link="${escapeAttr(stationId)}" ${active ? "" : "disabled"}><i class="fa-solid fa-ban"></i> Revogar</button>
    </div>
  </section>`;
}

function fuelAdminDeactivateAccessUpdates(access = {}) {
  const updates = {};
  if (access.uid) updates[`usuariosByUid/${access.uid}/status`] = "inativo";
  if (access.email) updates[`usuarios/${emailKey(access.email)}/status`] = "inativo";
  return updates;
}

async function generateFuelStationUpdateLink(stationId) {
  if (!isMaster() || !stationId) return;
  const stations = collectFuelAdminStationsFromForm();
  const station = stations[stationId];
  if (!station) { showToast("Posto nao encontrado."); return; }

  const previousAccess = state.combustiveisLinks?.[stationId] || {};
  const password = `Oc!${fuelAdminSecureToken().slice(0, 28)}`;
  const emailSuffix = `${Date.now()}${Math.random().toString(36).slice(2, 8)}`;
  const email = `posto.${slugify(stationId).slice(0, 28) || "combustivel"}.${emailSuffix}@acesso.olacarlopolis.com`.toLowerCase();
  const authUser = await createAuthUserWithTemporaryPassword(email, password);
  await saveUserProfile({
    uid: authUser.uid,
    email,
    role: "cliente",
    clienteId: "",
    postoCombustivelId: stationId,
    status: "ativo",
    permissoes: { combustiveis_precos: true }
  });

  const access = {
    uid: authUser.uid,
    email,
    password,
    ativo: true,
    postoId: stationId,
    postoNome: station.nomeExibicao || station.razaoSocial || "Posto",
    geradoEm: Date.now(),
    geradoPor: state.user?.uid || "",
    tipo: "firebase-auth"
  };
  await update(ref(db), {
    ...fuelAdminDeactivateAccessUpdates(previousAccess),
    [`configuracoes/combustiveis/postos/${stationId}`]: station,
    [`combustiveisLinks/${stationId}`]: access
  });
  state.combustiveisConfig = { ...state.combustiveisConfig, postos: stations };
  state.combustiveisLinks = { ...(state.combustiveisLinks || {}), [stationId]: access };
  renderFuelAdminSelectedStations();
  renderFuelAdminPromotions();
  bindFuelAdminWorkspaceTabs();
  setFuelAdminWorkspaceTab(fuelAdminActiveWorkspaceTab);
  const link = fuelAdminStationUpdateUrl(stationId, access);
  try { await navigator.clipboard.writeText(link); showToast("Link gerado e copiado."); }
  catch { showToast("Link gerado. Use o botao Copiar."); }
}

async function revokeFuelStationUpdateLink(stationId) {
  if (!isMaster() || !stationId || !state.combustiveisLinks?.[stationId]) return;
  if (!confirm("Revogar o link deste posto? O responsavel nao conseguira mais usa-lo.")) return;
  const access = state.combustiveisLinks[stationId];
  await update(ref(db), {
    ...fuelAdminDeactivateAccessUpdates(access),
    [`combustiveisLinks/${stationId}/ativo`]: false,
    [`combustiveisLinks/${stationId}/revogadoEm`]: Date.now(),
    [`combustiveisLinks/${stationId}/revogadoPor`]: state.user?.uid || ""
  });
  state.combustiveisLinks[stationId] = { ...access, ativo: false };
  renderFuelAdminSelectedStations();
  renderFuelAdminPromotions();
  bindFuelAdminWorkspaceTabs();
  setFuelAdminWorkspaceTab(fuelAdminActiveWorkspaceTab);
  showToast("Link revogado.");
}

const FUEL_ADMIN_MANUAL_CATALOG = [
  { key: "gasolina-comum", nome: "Gasolina Comum", tipo: "combustivel" },
  { key: "gasolina-aditivada", nome: "Gasolina Aditivada", tipo: "combustivel" },
  { key: "etanol", nome: "Etanol", tipo: "combustivel" },
  { key: "diesel-s10", nome: "Diesel S10", tipo: "combustivel" },
  { key: "diesel-s500", nome: "Diesel Comum S500", tipo: "combustivel" },
  { key: "gnv", nome: "GNV", tipo: "combustivel" },
  { key: "arla-32", nome: "ARLA 32", tipo: "lubrificante" }
];

function fuelAdminProductKind(productId = "", product = {}) {
  const value = normalizeName(`${productId} ${product.nome || ""} ${product.nomeAnp || ""}`).replace(/[^a-z0-9]/g, "");
  if (value.includes("arla32")) return "arla-32";
  if (value.includes("gasolina") && (value.includes("aditiv") || value.includes("ipimax"))) return "gasolina-aditivada";
  if (value.includes("gasolina")) return "gasolina-comum";
  if (value.includes("diesel") && value.includes("s500")) return "diesel-s500";
  if (value.includes("diesel") && value.includes("s10")) return "diesel-s10";
  if (value.includes("etanol") || value.includes("alcool")) return "etanol";
  if (value.includes("gnv") || value.includes("gasnaturalveicular")) return "gnv";
  return "";
}

function fuelAdminFriendlyProductName(name = "") {
  const kind = fuelAdminProductKind("", { nome: name });
  return FUEL_ADMIN_MANUAL_CATALOG.find((item) => item.key === kind)?.nome || String(name || "").trim();
}

function fuelAdminManualOptions(station) {
  const existingKinds = new Set(Object.entries(fuelAdminProductMap(station)).map(([productId, product]) => fuelAdminProductKind(productId, product)).filter(Boolean));
  return FUEL_ADMIN_MANUAL_CATALOG.filter((item) => !existingKinds.has(item.key));
}

function normalizeAnpStationForAdmin(station) {
  const id = String(station?.codigoSIMP || station?.cnpj || "").replace(/[^a-zA-Z0-9_-]/g, "");
  const existing = fuelAdminStationMap()[id] || {};
  const existingProducts = fuelAdminProductMap(existing);
  const combustiveis = {};
  (Array.isArray(station?.produtos) ? station.produtos : []).forEach((product) => {
    const nomeAnp = String(product?.produto || "").trim();
    if (!nomeAnp) return;
    const key = slugify(nomeAnp) || `combustivel-${Object.keys(combustiveis).length + 1}`;
    combustiveis[key] = {
      ...(existingProducts[key] || {}),
      nome: fuelAdminFriendlyProductName(nomeAnp),
      nomeAnp,
      ativo: existingProducts[key]?.ativo !== false,
      preco: Number(existingProducts[key]?.preco || 0) || 0,
      atualizadoEm: existingProducts[key]?.atualizadoEm || ""
    };
  });
  Object.entries(existingProducts).forEach(([key, product]) => {
    if (!combustiveis[key]) combustiveis[key] = product;
  });
  return {
    ...existing,
    dadosAnp: station && typeof station === "object" ? station : (existing.dadosAnp || {}),
    codigoSIMP: id,
    razaoSocial: station?.razaoSocial || existing.razaoSocial || "",
    nomeExibicao: existing.nomeExibicao || station?.razaoSocial || "",
    cnpj: station?.cnpj || existing.cnpj || "",
    endereco: station?.endereco || existing.endereco || "",
    complemento: station?.complemento || existing.complemento || "",
    bairro: station?.bairro || existing.bairro || "",
    cep: station?.cep || existing.cep || "",
    municipio: station?.municipio || existing.municipio || "",
    uf: station?.uf || existing.uf || "",
    distribuidora: station?.distribuidora || existing.distribuidora || "",
    latitude: station?.latitude || existing.latitude || "",
    longitude: station?.longitude || existing.longitude || "",
    ativo: existing.ativo !== false,
    combustiveis
  };
}

function collectFuelAdminStationsFromForm() {
  const result = {};
  $("fuelAdminSelectedStations")?.querySelectorAll("[data-fuel-station-id]").forEach((card) => {
    const id = card.dataset.fuelStationId;
    const base = fuelAdminStationMap()[id] || {};
    const combustiveis = {};
    card.querySelectorAll("[data-fuel-product-id]").forEach((row) => {
      const productId = row.dataset.fuelProductId;
      const preco = Number(String(row.querySelector("[data-fuel-price]")?.value || "").replace(",", ".")) || 0;
      const productBase = fuelAdminProductMap(base)[productId] || {};
      const dataInformada = row.querySelector("[data-fuel-date]")?.value || "";
      const precoNormalizado = Math.max(0, preco);
      const precoAlterado = Math.abs(precoNormalizado - Number(productBase.preco || 0)) >= 0.0005;
      const timestampAlteracao = precoAlterado ? Date.now() : 0;
      const product = {
        ...productBase,
        nome: row.dataset.fuelProductName || productId,
        ativo: row.querySelector("[data-fuel-enabled]")?.checked !== false,
        preco: precoNormalizado
      };
      if (precoAlterado) {
        product.atualizadoEm = fuelPanelSaoPauloDate(timestampAlteracao);
        product.atualizadoEmTimestamp = timestampAlteracao;
        product.origemAtualizacao = "painel";
      } else if (dataInformada) product.atualizadoEm = dataInformada;
      else delete product.atualizadoEm;
      combustiveis[productId] = product;
    });
    const horarios = emptySchedule();
    card.querySelectorAll("[data-fuel-schedule-day]").forEach((row) => {
      const day = row.dataset.fuelScheduleDay;
      if (!day || row.querySelector("[data-fuel-schedule-open]")?.checked !== true) return;
      if (row.querySelector("[data-fuel-schedule-all-day]")?.checked === true) {
        horarios[day] = [{ inicio: "00:00", fim: "23:59", vinteQuatroHoras: true }];
        return;
      }
      const slots = [];
      [0, 1].forEach((index) => {
        const inicio = row.querySelector(`[data-fuel-schedule-slot="${index}"][data-field="inicio"]`)?.value || "";
        const fim = row.querySelector(`[data-fuel-schedule-slot="${index}"][data-field="fim"]`)?.value || "";
        if (inicio && fim) slots.push({ inicio, fim });
      });
      horarios[day] = slots;
    });
    result[id] = {
      ...base,
      codigoSIMP: id,
      nomeExibicao: card.querySelector("[data-fuel-station-name]")?.value.trim() || base.razaoSocial || "Posto",
      menorPrecoCodigo: card.querySelector("[data-fuel-menor-preco-code]")?.value.trim() || "",
      imagem: card.querySelector("[data-fuel-station-image]")?.value.trim() || "",
      ativo: card.querySelector("[data-fuel-station-active]")?.checked !== false,
      horarios,
      combustiveis
    };
  });
  return result;

}
